// Native LiftBridge04 detailed moving side frames and their lower connectors; generated by Lift04MovingSideFrames.py.
// Bone 2, original Y/Z and triangle connectivity are preserved.
using System;
using UnityEngine;

namespace BridgeBuilder.Bridges;

internal static class Lift04MovingSideFrames
{
    internal static void ApplyDetailed(int lod, Vector3[] source, Vector3[] positions, float delta)
    {
        var data = lod switch
        {
            0 => (Count: 60636, Parts: Level0),
            1 => (Count: 45780, Parts: Level1),
            _ => throw new ArgumentOutOfRangeException(nameof(lod))
        };
        if (source.Length != data.Count || positions.Length != data.Count || !float.IsFinite(delta))
            throw new InvalidOperationException("Lift04 detailed moving side frames requires its recorded native topology.");
        foreach (var part in data.Parts)
            for (var i = part.First; i <= part.Last; i++)
                positions[i].x = source[i].x + part.Sign * delta;
    }

